import{_ as r,C as o,o as a,c as i,E as d,a0 as s}from"./chunks/framework.CV8GZ7IB.js";const f=JSON.parse('{"title":"Microsphere Projects — Java / Spring 生态分层增强体系","description":"Microsphere Projects 官方站点，32 个子项目、五层架构、统一 BOM 与版本矩阵。","frontmatter":{"layout":"page","title":"Microsphere Projects — Java / Spring 生态分层增强体系","description":"Microsphere Projects 官方站点，32 个子项目、五层架构、统一 BOM 与版本矩阵。","outline":false},"headers":[],"relativePath":"zh/index.md","filePath":"zh/index.md","lastUpdated":null}'),c={name:"zh/index.md"};function n(h,e,p,l,g,m){const t=o("HomeHero");return a(),i("div",null,[d(t),e[0]||(e[0]=s('<hr><h2 id="一分钟了解-microsphere" tabindex="-1">一分钟了解 Microsphere <a class="header-anchor" href="#一分钟了解-microsphere" aria-label="Permalink to &quot;一分钟了解 Microsphere&quot;">​</a></h2><p>Microsphere Projects 是一个由 <strong>36 个 GitHub 仓库</strong>组成的开源组织，围绕 Java 与 Spring 生态提供分层增强。 它不是一个单一框架，而是一套<strong>可以按需组合的能力矩阵</strong>：你可以只用最底部的 <code>microsphere-java</code> 作为工具库， 也可以引入 Spring Cloud 增强实现免重启的 Feign 配置刷新，再往上叠加可观测性、国际化与多活路由。</p><p>所有项目共享同一套工程约定：</p><ul><li><strong>统一 Group ID</strong> — <code>io.github.microsphere-projects</code></li><li><strong>统一 BOM 治理</strong> — 每个子项目都提供 <code>*-dependencies</code> 模块，导入一次即可对齐全部版本</li><li><strong>统一构建口径</strong> — <code>microsphere-build</code> 父 POM 覆盖 Java 8 / 11 / 17 / 21 / 25</li><li><strong>双版本线</strong> — <code>main</code> 面向新一代（Spring Boot 3/4、Spring Cloud 2022–2025），<code>1.x</code> 面向存量（Spring Boot 2、Hoxton–2021）</li></ul><h2 id="哪些场景适合用它" tabindex="-1">哪些场景适合用它 <a class="header-anchor" href="#哪些场景适合用它" aria-label="Permalink to &quot;哪些场景适合用它&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>对应能力</th><th>入口项目</th></tr></thead><tbody><tr><td>启动慢，Bean 初始化串行</td><td>解析依赖图，并发生成互不依赖的单例</td><td><a href="/zh/projects/microsphere-spring">Spring</a></td></tr><tr><td>改一次配置就要重启发布</td><td>配置变更驱动 Feign / 属性源 / i18n 消息热更新</td><td><a href="/zh/projects/microsphere-spring-cloud">Spring Cloud</a></td></tr><tr><td>线上想看 SQL 慢在哪</td><td>非侵入拦截 SQL 并接入 Micrometer</td><td><a href="/zh/projects/microsphere-observability">Observability</a></td></tr><tr><td>接口需要流控与熔断</td><td>统一模型覆盖 Web / DB / Redis</td><td><a href="/zh/projects/microsphere-alibaba-sentinel">Sentinel</a></td></tr><tr><td>多语言消息要集中管理</td><td>分层消息源 + 集中式 i18n Server</td><td><a href="/zh/projects/microsphere-i18n">i18n</a></td></tr><tr><td>同一实例要注册到多个注册中心</td><td>统一 API 多注册中心 + 联合 DiscoveryClient</td><td><a href="/zh/projects/microsphere-spring-cloud">Spring Cloud</a></td></tr><tr><td>多活单元化，优先同区调用</td><td>Zone 感知路由与跨区兜底</td><td><a href="/zh/projects/microsphere-multiactive">Multiactive</a></td></tr><tr><td>网关路由不想在每个服务里重复写</td><td><code>we://</code> 协议基于服务发现动态路由</td><td><a href="/zh/projects/microsphere-gateway">Gateway</a></td></tr></tbody></table><h2 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to &quot;接下来&quot;">​</a></h2><ul><li><a href="/zh/architecture">架构大图</a> — 五层架构与全部子项目的交互关系，可交互查看</li><li><a href="/zh/projects/">子项目总览</a> — 支持搜索、按分层/热度/名称排序的完整清单</li><li><a href="/zh/guide/getting-started">快速开始</a> — 从引入 BOM 到跑通第一个特性</li></ul>',9))])}const _=r(c,[["render",n]]);export{f as __pageData,_ as default};
